<div class="stats"><div class="stat"><span>Total Items</span><b><?=$stats['items']?></b><small>Inventory master</small></div><div class="stat"><span>Low Stock</span><b><?=$stats['low']?></b><small>Need reorder</small></div><div class="stat"><span>Stock Value</span><b><?=money($stats['value'])?></b><small>Current average cost</small></div><div class="stat"><span>Direct / Both</span><b><?=$stats['direct']?></b><small>Can sell directly</small></div></div><section class="panel"><div class="panel-head"><div><h2>Inventory Item List</h2><p>Raw materials, direct-sale items and Both-mode stock</p></div><div class="spacer"></div><button class="btn" data-open="catModal">+ Category</button><button class="btn primary" data-open="itemModal">+ New Item</button></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Category</th><th>Usage</th><th>On Hand</th><th>Purchase Unit</th><th>Avg Cost</th><th>Reorder</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?=e($i['name'])?></b><br><small><?=e($i['sku'])?></small></td><td><?=e($i['category_name']??'—')?></td><td><span class="tag blue"><?=e($i['usage_mode'])?></span></td><td><?=number_format((float)$i['qty_on_hand'],3)?> <?=e($i['unit_code'])?></td><td><?=e($i['purchase_unit_name'])?> × <?=number_format((float)$i['purchase_factor'],3)?></td><td><?=money((float)$i['avg_cost_per_stock_unit']*(float)$i['purchase_factor'])?></td><td><?=number_format((float)$i['reorder_level'],3)?></td></tr><?php endforeach;?></tbody></table></div></div></section><div class="modal" id="catModal"><div class="dialog" style="max-width:450px"><div class="dialog-head"><h3>Create Inventory Category</h3><button class="close" type="button" data-close>×</button></div><form method="post" action="/?r=inventory-category-create"><div class="dialog-body"><?=csrf_field()?><label><span>Name</span><input name="name" required></label></div><div class="dialog-foot"><button class="btn" type="button" data-close>C